import logging
from taf.rfrl.bts.devices.exceptions import AlarmIsActive, AlarmIsNotActive
from taf.rfrl.bts.devices.cu.generic_cu import GenericCu, login_logout


class CuAlarmVerification(GenericCu):
    """CU(Centralized Unit) alarm verification keywords for gNB"""

    @login_logout
    def verify_alarm_is_active(self, fault_id, fault_name, alarm_id, bts_id=0):
        """
        Verify given fault identified by fault_id/fault_name/alarm_id is active
        :param fault_id: Id of expected fault (for example 4350)
        :param fault_name: Name of expected fault (for example 'RAP or VM unavailable for Cloud')
        :param alarm_id: Id of expected alarm (for example 7101)
        :param bts_id: ID of BTS
        :return: None
        """
        for alarm in self.cu.get_active_alarms()['alarms']:
            if alarm['fault_id'] == fault_id and alarm['fault_name'] == fault_name \
                    and alarm['alarm_id'] == int(alarm_id):
                logging.debug("fault_id: %s is active as expected", fault_id)
                return
        raise AlarmIsNotActive("fault_id: {} fault_name: {} alarm_id: {} "
                               "is not active".format(fault_id, fault_name, alarm_id))

    @login_logout
    def verify_alarm_is_not_active(self, fault_id, fault_name=None, alarm_id=None, alarm_name=None, bts_id=0):
        """
        Verify given fault identified by fault_id is (and optionally fault_name/alarm_id/alarm_name) not active
        :param fault_id: Id of unwanted fault (for example 4350)
        :param fault_name: Name of unwanted fault (for example 'RAP or VM unavailable for Cloud')
        :param alarm_id: Id of unwanted alarm (for example 7220)
        :param alarm_name: Id of unwanted alarm (for example 'BASE STATION SECURITY PROBLEM')
        :param bts_id: ID of BTS
        :return: None
        """
        for alarm in self.cu.get_active_alarms()['alarms']:
            fault_id_match = (alarm['fault_id'] == fault_id)
            fault_name_match = True if (fault_name is None) else (alarm['fault_name'] == fault_name)
            alarm_id_match = True if (alarm_id is None) else (alarm['alarm_id'] == int(alarm_id))
            alarm_name_match = True if (alarm_name is None) else (alarm['alarm_name'] == alarm_name)
            if fault_id_match and fault_name_match and alarm_id_match and alarm_name_match:
                raise AlarmIsActive("fault_id: {} should not be active".format(fault_id))
        logging.debug("fault_id: %s is not active as expected", fault_id)
